using UnityEngine;using UnityEditor;using System.Linq;using System.Text;
public static class InspectMower{public static string Main(){var s=new StringBuilder();foreach(var root in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None).Where(t=>t.name=="Lawnmower"||t.name.Contains("Tow_Trailer"))){s.AppendLine("ROOT "+root.name+" pos="+root.position+" rot="+root.eulerAngles+" scale="+root.lossyScale);foreach(var t in root.GetComponentsInChildren<Transform>(true)){var f=t.GetComponent<MeshFilter>();s.AppendLine(t.name+" local="+t.localPosition+" rot="+t.localEulerAngles+" bounds="+(f?f.sharedMesh.bounds.ToString():"")+" world="+(t.GetComponent<Renderer>()?t.GetComponent<Renderer>().bounds.ToString():"")+" comps="+string.Join(",",t.GetComponents<Component>().Select(c=>c.GetType().Name)));}}
foreach(var b in Object.FindObjectsByType<BicycleController>(FindObjectsSortMode.None).Where(b=>!b.motorDriven)){s.AppendLine("BIKE "+b.transform.lossyScale+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(b));foreach(var t in b.cargoSlots)s.AppendLine(t.name+" local="+t.localPosition+" children="+t.childCount);}
return s.ToString();}}
